entry.summary:
you can use it with any layout component. For example, you could use a Group component which has no styling associated with it:
public static function configure(Schema $schema): Schema
    {
        return $schema
            ->components([
                    Group::make()
                    ->schema([
                        Section::make()
                            ->schema([
                                TextInput::make('test1'),
                            ])
                    ])->columnSpan(['lg' => 2]),
                Group::make()
                    ->schema([
                        Section::make()
                            ->schema([
                                TextInput::make('test2'),
                            ])
                    ])->columnSpan(['lg' => 1]),
            ])->columns(3);
    }

Forms\Components\Select::make('employee_id')->label('recipient')
                        ->options(function(){
                            return Employee::query()->active()
                            ->pluck('name', 'id')
                            ->toBase() 
                            ->put('other', 'other') 
                            ->toArray();
                        })
                        ->reactive()
                        ->required(),
